fun check(path, kind, v) = kind match {
  case "String" -> if (v is String) [] else ["$(path) must be a String"]
  case "Number" -> if (v is Number) [] else ["$(path) must be a Number"]
  case "Boolean" -> if (v is Boolean) [] else ["$(path) must be a Boolean"]
  case "Object" -> if (v is Object) [] else ["$(path) must be an Object"]
  case "Array" -> if (v is Array) [] else ["$(path) must be an Array"]
}
fun validate(path, schema, record) =
  flatten(schema pluck ((rule, field) -> do {
    var p = "$(path)$(field)"
    var v = record[field]
    ---
    if (v == null)
      (if (rule.required default false) ["$(p) is required"] else [])
    else if (rule.kind == "Object")
      (if (v is Object) validate("$(p).", rule.fields default {}, v) else ["$(p) must be an Object"])
    else if (rule.kind == "Array")
      (if (v is Array) flatten(v map ((item, idx) -> check("$(p)[$(idx)]", rule.itemKind default "String", item))) else ["$(p) must be an Array"])
    else check(p, rule.kind, v)
  }))
---
